/** Bounded generic walk: ordinary held movement keys steered from a read-only pose. */
const MAX_WALK_MS = MAX_WAIT_MS;
const WALK_DEFAULTS = { forwardKey: 'KeyW', leftKey: 'KeyA', rightKey: 'KeyD',
  posePointer: '/state/systemFlight/pose/position', headingPointer: '/state/systemFlight/pose/quaternion',
  arriveWithin: 3, noProgressMs: 4_000, minProgress: 0.25, tickMs: 200 };""")

# walk validation appended in validateAction before `return action;`
